if chunks:seq.append(''.join(chunks))
gc=np.array([(z.count('G')+z.count('C'))/len(z) for z in seq]); use=tot>=30; y=(lfc>2)&use; control=(lfc<=2)&use
# strata: fine GC, peak length, total count; require both outcome types
gb=np.clip((gc/.02).astype(int),0,49); lb=np.clip((np.log2(lens)-6).astype(int),0,7); cb=np.clip((np.log2(tot)-4).astype(int),0,12); strata=gb*1000+lb*20+cb
for pv in [1e-3,1e-4,1e-5]:
 print('p',pv)
 for j,nm in enumerate(names):
  cut=MOODS.tools.threshold_from_p(mats[j],bg,pv); hit=s[:,j]>=cut; num=den=0.; nstr=0
  for st in np.unique(strata[use]):
   z=(strata==st)&use; a=np.sum(z&y&hit); b=np.sum(z&y&~hit); c=np.sum(z&control&hit); d=np.sum(z&control&~hit); nt=a+b+c+d
   if (a+b)>0 and (c+d)>0:
